  | n -> invalid_arg (Printf.sprintf "Text.control_char_name: %d" n)





let escape_render ~keep_newlines s =
  let n = String.length s in
  let buf = Buffer.create n in
  let add_control code =
    Buffer.add_char buf '<';
    Buffer.add_string buf (control_char_name code);
    Buffer.add_char buf '>'
  in
  let add_non_ascii_byte c =
    Buffer.add_string buf (Printf.sprintf "<0x%02X>" (Char.code c))
  in
  let i = ref 0 in
  while !i < n do
    let advance =
      match s.[!i] with
      | '\\' ->
          Buffer.add_string buf "\\\\";
          1
      | '<' ->
          Buffer.add_string buf "\\<";
          1
      | '\t' ->
          Buffer.add_char buf '\t';
          1
      | '\n' when keep_newlines ->
          Buffer.add_char buf '\n';
          1
      | '\r' when keep_newlines && is_lf_at s (!i + 1) ->
          Buffer.add_char buf '\r';
          1
      | c when Char.code c < 0x20 || Char.code c = 0x7F ->
          add_control (Char.code c);
          1
      | c when Char.code c < 0x80 ->
          Buffer.add_char buf c;


